import json
def load_tok(d):
    am=np.load(d+'attention_mask.npy').astype(bool)
    H={L:np.load(d+f'token_hidden_L{L}.npy') for L in [0,6,11]}
    return am,H
toks={L:[] for L in [0,6,11]}; sid=[]
for k,d in enumerate(['pass_4/','pass_5/']):
    am,H=load_tok(d)
    for i in range(am.shape[0]):
        for L in [0,6,11]: toks[L].append(H[L][i][am[i]])
        sid+= [k*64+i]*am[i].sum()
T={L:np.concatenate(toks[L]) for L in [0,6,11]}; sid=np.array(sid)
np.savez('tok128.npz', sid=sid, **{f'T{L}':T[L] for L in T})
print(T[0].shape)
# held-out R2 token-level
tr=sid%2==0; te=~tr
for src in [11,6]:
    X=T[src]; Yt=T[0]; mx=X[tr].mean(0); my=Yt[tr].mean(0)
    for lam in [1,10,100,1000]:
        R=np.linalg.solve((X[tr]-mx).T@(X[tr]-mx)+lam*np.eye(768),(X[tr]-mx).T@(Yt[tr]-my))
        pr=(X[te]-mx)@R+my
        print(src,lam,'tokR2',round(1-((pr-Yt[te])**2).sum()/((Yt[te]-my)**2).sum(),3))
